/**
 * Types for the client_health_summary VIEW (S18 migration).
 *
 * This view is not in generated types — access via rawQuery bridge.
 * Definition: supabase/migrations/20260423100100_s18b_health_summary_view.sql
 */

export type HealthAlertCategory = 'allergies' | 'medical' | 'skin'

export interface ClientHealthSummaryRow {
  client_id: string
  studio_id: string
  allergy_count: number
  medical_count: number
  skin_count: number
  /** Count of pinned notes across allergies/medical/skin/emergency_contact */
  critical_pinned_count: number
  /** Distinct alert categories that have at least one note */
  alert_categories: HealthAlertCategory[]
  /** ISO timestamp of most-recent allergy or medical note update */
  last_medical_update: string | null
}

/**
 * Health summary fetching helpers — server-side only.
 *
 * Both functions use the rawQuery bridge to access the client_health_summary VIEW
 * which is not yet in generated types.
 *
 * RLS on the view inherits from client_notes policies (security_invoker=true).
 */

import type { SupabaseClient } from '@supabase/supabase-js'
import { rawQuery } from '@/lib/supabase/raw-query'
import type { ClientHealthSummaryRow } from './health-types'

/**
 * Fetch the health summary for a single client.
 * Returns null on RLS denial, missing data, or query error.
 */
export async function fetchClientHealthSummary(
  supabase: SupabaseClient,
  clientId: string,
  studioId: string,
): Promise<ClientHealthSummaryRow | null> {
  const { data, error } = await rawQuery<ClientHealthSummaryRow>(supabase, 'client_health_summary')
    .select('client_id, studio_id, allergy_count, medical_count, skin_count, critical_pinned_count, alert_categories, last_medical_update')
    .eq('client_id', clientId)
    .eq('studio_id', studioId)
    .single()

  if (error || !data) return null
  return data
}

/**
 * Batch-fetch health summaries for a list of client IDs.
 * Returns a Map keyed by client_id.
 * Clients with no notes (or RLS-denied) are absent from the map.
 */
export async function fetchClientHealthSummariesForIds(
  supabase: SupabaseClient,
  clientIds: string[],
  studioId: string,
): Promise<Map<string, ClientHealthSummaryRow>> {
  if (clientIds.length === 0) return new Map()

  const { data, error } = await rawQuery<ClientHealthSummaryRow>(supabase, 'client_health_summary')
    .select('client_id, studio_id, allergy_count, medical_count, skin_count, critical_pinned_count, alert_categories, last_medical_update')
    .eq('studio_id', studioId)
    .in('client_id', clientIds)

  const map = new Map<string, ClientHealthSummaryRow>()
  if (error || !data) return map

  for (const row of data) {
    map.set(row.client_id, row)
  }
  return map
}

'use client'

import { useEffect, useState } from 'react'
import { TriangleAlert } from 'lucide-react'
import Link from 'next/link'
import { cn } from '@/lib/utils'
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip'
import type { ClientHealthSummaryRow } from '@/lib/clients/health-types'

interface HealthAlertBadgeProps {
  summary: ClientHealthSummaryRow | null
  variant: 'dot' | 'chip' | 'strip'
  /** Only used by 'strip' variant — the client profile path for "Review notes" link */
  clientId?: string
  className?: string
}

/**
 * Renders a health alert indicator based on the client's health summary.
 *
 * Returns null when there are no critical pinned notes.
 *
 * Variants:
 *  - dot: 6px pulsing red circle (tables, search results)
 *  - chip: red pill with warning icon + count (hero beside name)
 *  - strip: full-width red banner with category list + review link (booking drawers)
 */
export function HealthAlertBadge({ summary, variant, clientId, className }: HealthAlertBadgeProps) {
  const [pulse, setPulse] = useState(true)

  // Stop pulse animation after 2s — draws attention on mount but doesn't distract indefinitely
  useEffect(() => {
    if (!pulse) return
    const timer = setTimeout(() => setPulse(false), 2000)
    return () => clearTimeout(timer)
  }, [pulse])

  if (!summary || summary.critical_pinned_count === 0) return null

  const categoryLabels = summary.alert_categories.map((c) => {
    switch (c) {
      case 'allergies': return 'Allergies'
      case 'medical': return 'Medical'
      case 'skin': return 'Skin conditions'
      default: return c
    }
  })
  const categoryText = categoryLabels.join(', ')

  if (variant === 'dot') {
    return (
      <Tooltip>
        <TooltipTrigger render={
          <span
            role="img"
            aria-label={`Medical alerts: ${categoryText}`}
            className={cn(
              'inline-block h-2 w-2 rounded-full bg-destructive shrink-0',
              pulse && 'animate-pulse',
              className,
            )}
          />
        } />
        <TooltipContent side="right">
          <p className="text-xs font-medium">Medical alerts — review before booking</p>
          <p className="text-xs text-muted-foreground">{categoryText}</p>
        </TooltipContent>
      </Tooltip>
    )
  }

  if (variant === 'chip') {
    return (
      <Tooltip>
        <TooltipTrigger render={
          <span
            role="img"
            aria-label={`${summary.critical_pinned_count} medical alert${summary.critical_pinned_count !== 1 ? 's' : ''}: ${categoryText}`}
            className={cn(
              'inline-flex items-center gap-1 rounded-full border border-destructive/40 bg-destructive/10 px-2 py-0.5 text-xs font-medium text-destructive',
              pulse && 'animate-pulse',
              className,
            )}
          >
            <TriangleAlert className="h-3 w-3 shrink-0" aria-hidden="true" />
            {summary.critical_pinned_count} alert{summary.critical_pinned_count !== 1 ? 's' : ''}
          </span>
        } />
        <TooltipContent>
          <p className="text-xs font-medium">Pinned medical/allergy notes</p>
          <p className="text-xs text-muted-foreground">{categoryText}</p>
        </TooltipContent>
      </Tooltip>
    )
  }

  // strip variant
  return (
    <div
      role="alert"
      className={cn(
        'flex items-start gap-3 rounded-lg border border-destructive/40 bg-destructive/8 px-4 py-3',
        className,
      )}
    >
      <TriangleAlert className="h-4 w-4 shrink-0 text-destructive mt-0.5" aria-hidden="true" />
      <div className="flex-1 min-w-0">
        <p className="text-sm font-semibold text-destructive">
          This client has {summary.critical_pinned_count} medical alert{summary.critical_pinned_count !== 1 ? 's' : ''}
        </p>
        <p className="text-xs text-destructive/80 mt-0.5">{categoryText}</p>
      </div>
      {clientId && (
        <Link
          href={`/clients/${clientId}/notes?category=medical`}
          target="_blank"
          rel="noopener noreferrer"
          className="shrink-0 text-xs font-medium text-destructive underline underline-offset-2 hover:no-underline"
        >
          Review notes
        </Link>
      )}
    </div>
  )
}

