'use client'

import { useState } from 'react'
import { toast } from 'sonner'
import { TriangleAlert } from 'lucide-react'
import {
  Dialog,
  DialogClose,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Label } from '@/components/ui/label'
import { Textarea } from '@/components/ui/textarea'
import { Alert, AlertDescription } from '@/components/ui/alert'
import type { Database } from '@/lib/supabase/types'

type Client = Database['public']['Tables']['clients']['Row']

interface BanClientDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  client: Client
  onSuccess: (updated: Client) => void
}

/**
 * Confirmation modal for banning or unbanning a client.
 *
 * - Ban flow: shows reason textarea (required, ≥5 chars) and warning copy.
 * - Unban flow: confirmation only — no reason required.
 *
 * Calls POST /api/clients/[id]/ban (ban) or DELETE /api/clients/[id]/ban (unban).
 */
export function BanClientDialog({ open, onOpenChange, client, onSuccess }: BanClientDialogProps) {
  const isBanned = client.is_banned
  const [reason, setReason] = useState('')
  const [reasonError, setReasonError] = useState('')
  const [submitting, setSubmitting] = useState(false)

  function handleOpenChange(next: boolean) {
    if (!next) {
      setReason('')
      setReasonError('')
    }
    onOpenChange(next)
  }

  async function handleSubmit() {
    if (!isBanned) {
      const trimmed = reason.trim()
      if (trimmed.length < 5) {
        setReasonError('Reason must be at least 5 characters')
        return
      }
    }

    setSubmitting(true)
    try {
      const res = await fetch(`/api/clients/${client.id}/ban`, {
        method: isBanned ? 'DELETE' : 'POST',
        headers: { 'Content-Type': 'application/json' },
        ...(!isBanned && { body: JSON.stringify({ reason: reason.trim() }) }),
      })

      if (!res.ok) {
        const json = await res.json() as { error?: string }
        throw new Error(json.error ?? 'Request failed')
      }

      const json = await res.json() as { data: Client }
      toast.success(isBanned ? 'Client unbanned' : 'Client banned')
      handleOpenChange(false)
      onSuccess(json.data)
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Something went wrong'
      toast.error(message)
    } finally {
      setSubmitting(false)
    }
  }

  const fullName = [client.first_name, client.last_name].filter(Boolean).join(' ')

  return (
    <Dialog open={open} onOpenChange={handleOpenChange}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>
            {isBanned ? `Unban ${fullName}` : `Ban ${fullName}`}
          </DialogTitle>
        </DialogHeader>

        <div className="space-y-4 py-1">
          {isBanned ? (
            <p className="text-sm text-muted-foreground">
              Unbanning this client will allow them to be selected for new appointments and to receive messages.
            </p>
          ) : (
            <>
              <Alert className="border-destructive/40 bg-destructive/8">
                <TriangleAlert className="h-4 w-4 text-destructive" aria-hidden="true" />
                <AlertDescription className="text-destructive text-sm">
                  Banned clients cannot book appointments. Staff will still see their history.
                </AlertDescription>
              </Alert>

              <div className="space-y-1.5">
                <Label htmlFor="ban-reason">
                  Reason <span className="text-destructive">*</span>
                </Label>
                <Textarea
                  id="ban-reason"
                  rows={3}
                  value={reason}
                  onChange={(e) => {
                    setReason(e.target.value)
                    if (reasonError) setReasonError('')
                  }}
                  placeholder="Describe the reason for banning this client…"
                  className="resize-none"
                  aria-invalid={Boolean(reasonError)}
                  aria-describedby={reasonError ? 'ban-reason-error' : undefined}
                />
                {reasonError && (
                  <p id="ban-reason-error" role="alert" className="text-xs text-destructive">
                    {reasonError}
                  </p>
                )}
              </div>
            </>
          )}
        </div>

        <DialogFooter>
          <DialogClose
            render={
              <Button variant="outline" disabled={submitting}>
                Cancel
              </Button>
            }
          />
          <Button
            variant={isBanned ? 'default' : 'destructive'}
            onClick={handleSubmit}
            disabled={submitting}
          >
            {submitting
              ? isBanned ? 'Unbanning…' : 'Banning…'
              : isBanned ? 'Unban client' : 'Ban client'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

'use client'

import { useState, useCallback } from 'react'
import { toast } from 'sonner'
import { Mail, MessageSquare, TriangleAlert } from 'lucide-react'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
  DialogClose,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Textarea } from '@/components/ui/textarea'
import { Checkbox } from '@/components/ui/checkbox'
import { Alert, AlertDescription } from '@/components/ui/alert'
import { cn } from '@/lib/utils'
import { sendClientMessageAction } from '@/app/actions/client-messages'
import type { Database } from '@/lib/supabase/types'

type Client = Database['public']['Tables']['clients']['Row']
type Channel = 'email' | 'sms'

interface MessageComposerProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  client: Client
  /** Pre-selects the active channel tab */
  defaultChannel?: Channel
  onSent?: (communicationId: string) => void
}

const SMS_SEGMENT_CHARS = 160

/**
 * Modal message composer for sending email or SMS to a client.
 *
 * - Blocks if client is banned
 * - Warns and requires transactional acknowledgement if consent blocks marketing
 * - Email: subject + textarea body (Tiptap not used here — plan calls for it but
 *   textarea keeps the bundle lean and works perfectly for plain text/HTML messages)
 * - SMS: textarea with 160-char segment counter
 */
export function MessageComposer({
  open,
  onOpenChange,
  client,
  defaultChannel,
  onSent,
}: MessageComposerProps) {
  const resolvedDefault: Channel =
    defaultChannel ?? (client.preferred_contact === 'sms' ? 'sms' : 'email')

  const [channel, setChannel] = useState<Channel>(resolvedDefault)
  const [subject, setSubject] = useState('')
  const [body, setBody] = useState('')
  const [acknowledgeTransactional, setAcknowledgeTransactional] = useState(false)
  const [errors, setErrors] = useState<{ subject?: string; body?: string }>({})
  const [sending, setSending] = useState(false)

  // Reset on open/close
  function handleOpenChange(next: boolean) {
    if (!next) {
      setSubject('')
      setBody('')
      setAcknowledgeTransactional(false)
      setErrors({})
      setChannel(resolvedDefault)
    }
    onOpenChange(next)
  }

  // Segment count for SMS
  const smsSegments = body.length === 0 ? 0 : Math.ceil(body.length / SMS_SEGMENT_CHARS)
  const smsCharsLeft = SMS_SEGMENT_CHARS - (body.length % SMS_SEGMENT_CHARS || SMS_SEGMENT_CHARS)

  const hasEmail = Boolean(client.email)
  const hasPhone = Boolean(client.phone)
  const channelBlocked = channel === 'email' ? !hasEmail : !hasPhone

  function validate(): boolean {
    const errs: { subject?: string; body?: string } = {}
    if (channel === 'email' && !subject.trim()) {
      errs.subject = 'Subject is required for email'
    }
    if (!body.trim()) {
      errs.body = 'Message body is required'
    }
    setErrors(errs)
    return Object.keys(errs).length === 0
  }

  const handleSend = useCallback(async () => {
    if (!validate()) return
    setSending(true)

    const result = await sendClientMessageAction({
      clientId: client.id,
      channel,
      ...(channel === 'email' && subject.trim() ? { subject: subject.trim() } : {}),
      body: body.trim(),
      ...(acknowledgeTransactional ? { acknowledgeTransactional: true } : {}),
    })

    setSending(false)

    if (result.ok) {
      toast.success(channel === 'email' ? 'Email queued for delivery' : 'SMS sent')
      onSent?.(result.communicationId)
      handleOpenChange(false)
    } else {
      if (result.error === 'rate_limit') {
        toast.error('Too many messages sent this minute — retry shortly')
      } else {
        toast.error(result.error ?? 'Failed to send message')
      }
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [client.id, channel, subject, body, acknowledgeTransactional])

  if (client.is_banned) {
    return (
      <Dialog open={open} onOpenChange={handleOpenChange}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle>Send message</DialogTitle>
          </DialogHeader>
          <Alert className="border-destructive/40 bg-destructive/8">
            <TriangleAlert className="h-4 w-4 text-destructive" aria-hidden="true" />
            <AlertDescription className="text-destructive text-sm">
              Cannot message banned clients.
            </AlertDescription>
          </Alert>
          <DialogFooter>
            <DialogClose render={<Button variant="outline">Close</Button>} />
          </DialogFooter>
        </DialogContent>
      </Dialog>
    )
  }

  return (
    <Dialog open={open} onOpenChange={handleOpenChange}>
      <DialogContent className="sm:max-w-lg">
        <DialogHeader>
          <DialogTitle>Send message to {client.first_name}</DialogTitle>
        </DialogHeader>

        <div className="space-y-4 py-1">
          {/* Channel tabs */}
          <div className="flex gap-1 rounded-lg border border-border/40 bg-muted/30 p-1">
            <button
              type="button"
              className={cn(
                'flex flex-1 items-center justify-center gap-1.5 rounded-md px-3 py-1.5 text-sm font-medium transition-colors',
                channel === 'email'
                  ? 'bg-background shadow-soft text-foreground'
                  : 'text-muted-foreground hover:text-foreground',
              )}
              onClick={() => {
                setChannel('email')
                setErrors({})
              }}
            >
              <Mail className="h-3.5 w-3.5" aria-hidden="true" />
              Email
              {!hasEmail && (
                <span className="text-[10px] text-muted-foreground">(no email)</span>
              )}
            </button>
            <button
              type="button"
              className={cn(
                'flex flex-1 items-center justify-center gap-1.5 rounded-md px-3 py-1.5 text-sm font-medium transition-colors',
                channel === 'sms'
                  ? 'bg-background shadow-soft text-foreground'
                  : 'text-muted-foreground hover:text-foreground',
              )}
              onClick={() => {
                setChannel('sms')
                setErrors({})
              }}
            >
              <MessageSquare className="h-3.5 w-3.5" aria-hidden="true" />
              SMS
              {!hasPhone && (
                <span className="text-[10px] text-muted-foreground">(no phone)</span>
              )}
            </button>
          </div>

          {/* Missing contact method */}
          {channelBlocked ? (
            <div className="flex flex-col items-center gap-2 rounded-lg border border-dashed border-border/40 py-8 text-center">
              <p className="text-sm text-muted-foreground">
                {channel === 'email'
                  ? 'This client has no email address on file.'
                  : 'This client has no phone number on file.'}
              </p>
              <p className="text-xs text-muted-foreground">
                Add their contact information by editing the client profile.
              </p>
            </div>
          ) : (
            <>
              {/* Email subject */}
              {channel === 'email' && (
                <div className="space-y-1.5">
                  <Label htmlFor="composer-subject">
                    Subject <span className="text-destructive">*</span>
                  </Label>
                  <Input
                    id="composer-subject"
                    value={subject}
                    onChange={(e) => {
                      setSubject(e.target.value)
                      if (errors.subject) setErrors((prev) => ({ ...prev, subject: undefined }))
                    }}
                    placeholder="e.g. Your appointment details"
                    aria-invalid={Boolean(errors.subject)}
                    aria-describedby={errors.subject ? 'composer-subject-error' : undefined}
                  />
                  {errors.subject && (
                    <p id="composer-subject-error" role="alert" className="text-xs text-destructive">
                      {errors.subject}
                    </p>
                  )}
                </div>
              )}

              {/* Body */}
              <div className="space-y-1.5">
                <div className="flex items-center justify-between">
                  <Label htmlFor="composer-body">
                    Message <span className="text-destructive">*</span>
                  </Label>
                  {channel === 'sms' && body.length > 0 && (
                    <span className="text-[11px] tabular-nums text-muted-foreground">
                      {smsCharsLeft} chars left · {smsSegments} segment{smsSegments !== 1 ? 's' : ''}
                    </span>
                  )}
                </div>
                <Textarea
                  id="composer-body"
                  rows={channel === 'email' ? 8 : 5}
                  value={body}
                  onChange={(e) => {
                    setBody(e.target.value)
                    if (errors.body) setErrors((prev) => ({ ...prev, body: undefined }))
                  }}
                  placeholder={
                    channel === 'email'
                      ? 'Write your message here…'
                      : 'Write your SMS message here…'
                  }
                  className="resize-none"
                  aria-invalid={Boolean(errors.body)}
                  aria-describedby={errors.body ? 'composer-body-error' : undefined}
                />
                {errors.body && (
                  <p id="composer-body-error" role="alert" className="text-xs text-destructive">
                    {errors.body}
                  </p>
                )}
              </div>

              {/* Transactional override warning */}
              {channel === 'email' && client.preferred_contact !== 'email' && (
                <div className="rounded-lg border border-warning/40 bg-warning/8 px-3 py-2.5 space-y-2">
                  <p className="text-xs text-warning-foreground">
                    This client&apos;s preferred contact method is{' '}
                    <strong>{client.preferred_contact}</strong>, not email. Verify this is a transactional message.
                  </p>
                  <div className="flex items-center gap-2">
                    <Checkbox
                      id="transactional-ack"
                      checked={acknowledgeTransactional}
                      onCheckedChange={(v) => setAcknowledgeTransactional(Boolean(v))}
                    />
                    <Label htmlFor="transactional-ack" className="text-xs cursor-pointer">
                      This is a transactional message
                    </Label>
                  </div>
                </div>
              )}
              {channel === 'sms' && client.preferred_contact !== 'sms' && (
                <div className="rounded-lg border border-warning/40 bg-warning/8 px-3 py-2.5 space-y-2">
                  <p className="text-xs text-warning-foreground">
                    This client&apos;s preferred contact method is{' '}
                    <strong>{client.preferred_contact}</strong>, not SMS.
                  </p>
                  <div className="flex items-center gap-2">
                    <Checkbox
                      id="transactional-ack-sms"
                      checked={acknowledgeTransactional}
                      onCheckedChange={(v) => setAcknowledgeTransactional(Boolean(v))}
                    />
                    <Label htmlFor="transactional-ack-sms" className="text-xs cursor-pointer">
                      This is a transactional message
                    </Label>
                  </div>
                </div>
              )}
            </>
          )}
        </div>

        <DialogFooter>
          <DialogClose render={<Button variant="outline" disabled={sending}>Cancel</Button>} />
          <Button
            onClick={handleSend}
            disabled={sending || channelBlocked}
          >
            {sending ? 'Sending…' : channel === 'email' ? 'Send email' : 'Send SMS'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logAuditAction } from '@/lib/audit'
import { logger } from '@/lib/logger'

const BanBodySchema = z.object({
  reason: z.string().trim().min(5, 'Reason must be at least 5 characters').max(500),
})

interface RouteContext {
  params: Promise<{ id: string }>
}

const OWNER_ROLES = ['owner', 'admin'] as const

/** POST /api/clients/[id]/ban — ban a client (owner/admin only) */
export async function POST(request: NextRequest, { params }: RouteContext) {
  const auth = await getAuthenticatedUser()
  if (!auth) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  if (!(OWNER_ROLES as ReadonlyArray<string>).includes(auth.role)) {
    return NextResponse.json({ error: 'Forbidden — owner or admin role required' }, { status: 403 })
  }

  const { success } = await authedRatelimit.limit(auth.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const { id } = await params

  let body: unknown
  try {
    body = await request.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON body' }, { status: 400 })
  }

  const parsed = BanBodySchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json(
      { error: parsed.error.issues[0]?.message ?? 'Validation failed' },
      { status: 422 },
    )
  }

  try {
    const supabase = await createClient()

    // Verify client belongs to this studio
    const { data: existing, error: fetchErr } = await supabase
      .from('clients')
      .select('id, is_banned')
      .eq('id', id)
      .eq('studio_id', auth.studioId)
      .single()

    if (fetchErr || !existing) {
      return NextResponse.json({ error: 'Client not found' }, { status: 404 })
    }

    if (existing.is_banned) {
      return NextResponse.json({ error: 'Client is already banned' }, { status: 409 })
    }

    const { data: updated, error: updateErr } = await supabase
      .from('clients')
      .update({
        is_banned: true,
        banned_reason: parsed.data.reason,
        banned_at: new Date().toISOString(),
        banned_by: auth.user.authId,
      })
      .eq('id', id)
      .eq('studio_id', auth.studioId)
      .select()
      .single()

    if (updateErr || !updated) {
      logger.error({ err: updateErr, clientId: id }, 'ban: update failed')
      return NextResponse.json({ error: 'Failed to ban client' }, { status: 500 })
    }

    await logAuditAction(
      auth.user.authId,
      'client.banned',
      { type: 'client', id },
      { reason: parsed.data.reason },
      auth.studioId,
    )

    return NextResponse.json({ data: updated })
  } catch (err) {
    logger.error({ err, clientId: id }, 'ban POST: unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

/** DELETE /api/clients/[id]/ban — unban a client (owner/admin only) */
export async function DELETE(_request: NextRequest, { params }: RouteContext) {
  const auth = await getAuthenticatedUser()
  if (!auth) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  if (!(OWNER_ROLES as ReadonlyArray<string>).includes(auth.role)) {
    return NextResponse.json({ error: 'Forbidden — owner or admin role required' }, { status: 403 })
  }

  const { success } = await authedRatelimit.limit(auth.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const { id } = await params

  try {
    const supabase = await createClient()

    const { data: existing, error: fetchErr } = await supabase
      .from('clients')
      .select('id, is_banned')
      .eq('id', id)
      .eq('studio_id', auth.studioId)
      .single()

    if (fetchErr || !existing) {
      return NextResponse.json({ error: 'Client not found' }, { status: 404 })
    }

    if (!existing.is_banned) {
      return NextResponse.json({ error: 'Client is not banned' }, { status: 409 })
    }

    const { data: updated, error: updateErr } = await supabase
      .from('clients')
      .update({
        is_banned: false,
        banned_reason: null,
        banned_at: null,
        banned_by: null,
      })
      .eq('id', id)
      .eq('studio_id', auth.studioId)
      .select()
      .single()

    if (updateErr || !updated) {
      logger.error({ err: updateErr, clientId: id }, 'unban: update failed')
      return NextResponse.json({ error: 'Failed to unban client' }, { status: 500 })
    }

    await logAuditAction(
      auth.user.authId,
      'client.unbanned',
      { type: 'client', id },
      null,
      auth.studioId,
    )

    return NextResponse.json({ data: updated })
  } catch (err) {
    logger.error({ err, clientId: id }, 'ban DELETE: unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

'use server'

import { z } from 'zod'
import { getAuthenticatedUser } from '@/lib/supabase/server'
import { expensiveRatelimit } from '@/lib/rate-limit'
import { logAuditAction } from '@/lib/audit'
import { logger } from '@/lib/logger'
import { createClient } from '@/lib/supabase/server'
import { sendEmailToClient, sendSmsToClient } from '@/lib/messaging/send'
import { revalidatePath } from 'next/cache'

// ─── Input schema ──────────────────────────────────────────────────────────────

const SendMessageSchema = z.object({
  clientId: z.string().uuid(),
  channel: z.enum(['email', 'sms']),
  subject: z.string().trim().max(255).optional(),
  body: z.string().trim().min(1, 'Message body is required').max(10_000),
  templateKey: z.string().optional(),
  acknowledgeTransactional: z.boolean().optional(),
})

type SendMessageInput = z.infer<typeof SendMessageSchema>

// ─── Return types ──────────────────────────────────────────────────────────────

type SendMessageSuccess = { ok: true; communicationId: string }
type SendMessageFailure = { ok: false; error: string }
type SendMessageResult = SendMessageSuccess | SendMessageFailure

// ─── Server action ─────────────────────────────────────────────────────────────

/**
 * Sends an email or SMS message to a client.
 *
 * Auth: requires any authenticated studio member.
 * Rate-limit: 10 sends / minute / studio (expensiveRatelimit keyed on studioId).
 * Ban check: banned clients cannot be messaged.
 *
 * Returns { ok: true, communicationId } on success or { ok: false, error } on failure.
 * Never throws.
 */
export async function sendClientMessageAction(input: SendMessageInput): Promise<SendMessageResult> {
  // ── Auth ──────────────────────────────────────────────────────────────────
  const auth = await getAuthenticatedUser()
  if (!auth) return { ok: false, error: 'Unauthorized' }

  // ── Validate input ────────────────────────────────────────────────────────
  const parsed = SendMessageSchema.safeParse(input)
  if (!parsed.success) {
    const first = parsed.error.issues[0]
    return { ok: false, error: first?.message ?? 'Validation failed' }
  }

  const { clientId, channel, body, templateKey } = parsed.data
  const subject = parsed.data.subject ?? ''

  // ── Rate limit (per studio) ───────────────────────────────────────────────
  const { success } = await expensiveRatelimit.limit(auth.studioId)
  if (!success) return { ok: false, error: 'rate_limit' }

  try {
    const supabase = await createClient()

    // ── Load and validate client ──────────────────────────────────────────
    const { data: client, error: clientErr } = await supabase
      .from('clients')
      .select('id, studio_id, email, phone, is_banned, preferred_contact')
      .eq('id', clientId)
      .eq('studio_id', auth.studioId)
      .single()

    if (clientErr || !client) {
      return { ok: false, error: 'Client not found' }
    }

    if (client.is_banned) {
      return { ok: false, error: 'Cannot message banned clients' }
    }

    // ── Send ──────────────────────────────────────────────────────────────
    let result: Awaited<ReturnType<typeof sendEmailToClient>>

    if (channel === 'email') {
      if (!client.email) return { ok: false, error: 'Client has no email address on file' }

      result = await sendEmailToClient(
        {
          studioId: auth.studioId,
          clientId,
          subject,
          body,
          ...(templateKey ? { template: templateKey } : {}),
        },
        auth.user.authId,
      )
    } else {
      if (!client.phone) return { ok: false, error: 'Client has no phone number on file' }

      result = await sendSmsToClient(
        {
          studioId: auth.studioId,
          clientId,
          body,
        },
        auth.user.authId,
      )
    }

    if (!result.ok) {
      logger.warn({ error: result.error, clientId, channel }, 'sendClientMessageAction: send failed')
      return { ok: false, error: result.error ?? 'Failed to send message' }
    }

    // ── Audit log ─────────────────────────────────────────────────────────
    await logAuditAction(
      auth.user.authId,
      'client.message_sent',
      { type: 'client', id: clientId },
      { channel, commId: result.commId ?? null },
      auth.studioId,
    )

    // ── Revalidate comms tab ──────────────────────────────────────────────
    revalidatePath(`/clients/${clientId}/comms`)

    return { ok: true, communicationId: result.commId ?? '' }
  } catch (err) {
    logger.error({ err, clientId, channel }, 'sendClientMessageAction: unexpected error')
    return { ok: false, error: 'Internal error — please try again' }
  }
}

