input.new_string:
function validate(): boolean {
  const newErrors: Partial<Record<keyof FormData, string>> = {}
  if (!form.first_name.trim()) newErrors.first_name = 'First name is required'
  if (form.email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(form.email)) {
    newErrors.email = 'Enter a valid email address'
  }
  // Social handle: no @ or / chars, 1-100 chars when provided
  const handleRegex = /^[^@/]{1,100}$/
  if (form.instagram_handle && !handleRegex.test(form.instagram_handle)) {
    newErrors.instagram_handle = 'No @ or / — just the username'
  }
  if (form.tiktok_handle && !handleRegex.test(form.tiktok_handle)) {
    newErrors.tiktok_handle = 'No @ or / — just the username'
  }
  if (form.website_url && !/^https?:\/\/.+/.test(form.website_url)) {
    newErrors.website_url = 'Must start with https:// or http://'
  }
  setErrors(newErrors)
  return Object.keys(newErrors).length === 0
}

