import { cn, formatCurrency, formatRelativeTime } from '@/lib/utils'
import type { Database } from '@/lib/supabase/types'
import type { ClientHealthSummaryRow } from '@/lib/clients/health-types'

type Client = Database['public']['Tables']['clients']['Row']

interface ConsentTemplate {
  id: string
  name: string
}

interface ClientProfileHeroProps {
  client: Client
  tags: ClientTag[]
  healthSummary?: ClientHealthSummaryRow | null
  consentTemplates?: ConsentTemplate[]
  nextBookingDate?: string | null
  /** Only owners/admins see ban/unban action */
  canBan?: boolean
  onNewAppointment?: () => void
  onSendConsent?: (templateId: string) => void
  onUploadPhoto?: () => void
  onArchive?: () => void
  onUnarchive?: () => void
  onEdit?: () => void
  onClientUpdate?: (updated: Client) => void
}

function ClientAvatar({ client, size = 72 }: { client: Client; size?: number }) {
  const initials = [client.first_name[0], client.last_name?.[0]]
    .filter(Boolean)
    .join('')
    .toUpperCase()

  return (
    <div
      className="client-avatar-hero rounded-full flex items-center justify-center text-white font-bold shrink-0 ring-2 ring-background"
      style={{ width: size, height: size, fontSize: size * 0.33 }}
      aria-label={`${client.first_name} ${client.last_name ?? ''}`}
    >
      {initials}
    </div>
  )
}

function SocialLinks({ client }: { client: Client }) {
  if (!client.instagram_handle && !client.tiktok_handle && !client.website_url) return null

  return (
    <div className="flex items-center gap-1.5" aria-label="Social profiles">
      {client.instagram_handle && (
        <Tooltip>
          <TooltipTrigger render={
            <a
              href={`https://instagram.com/${client.instagram_handle}`}
              target="_blank"
              rel="noopener noreferrer"
              className="inline-flex items-center justify-center h-6 w-6 rounded-full bg-muted hover:bg-muted/80 transition-colors"
              aria-label={`@${client.instagram_handle} on Instagram`}
            >
              <Instagram className="h-3.5 w-3.5 text-muted-foreground" aria-hidden="true" />
            </a>
          } />
          <TooltipContent>@{client.instagram_handle}</TooltipContent>
        </Tooltip>
      )}
      {client.tiktok_handle && (
        <Tooltip>
          <TooltipTrigger render={
            <a
              href={`https://tiktok.com/@${client.tiktok_handle}`}
              target="_blank"
              rel="noopener noreferrer"
              className="inline-flex items-center justify-center h-6 w-6 rounded-full bg-muted hover:bg-muted/80 transition-colors"
              aria-label={`@${client.tiktok_handle} on TikTok`}
            >
              <Music2 className="h-3.5 w-3.5 text-muted-foreground" aria-hidden="true" />
            </a>
          } />
          <TooltipContent>@{client.tiktok_handle} on TikTok</TooltipContent>
        </Tooltip>
      )}
      {client.website_url && (
        <Tooltip>
          <TooltipTrigger render={
            <a
              href={client.website_url}
              target="_blank"
              rel="noopener noreferrer"
