export function ClientProfileHero({
  client,
  tags,
  healthSummary,
  consentTemplates = [],
  nextBookingDate,
  canBan = false,
  onNewAppointment,
  onSendConsent,
  onUploadPhoto,
  onArchive,
  onUnarchive,
  onEdit,
  onClientUpdate,
}: ClientProfileHeroProps) {
  const [banDialogOpen, setBanDialogOpen] = useState(false)
  const [composerOpen, setComposerOpen] = useState(false)
  const [composerChannel, setComposerChannel] = useState<'email' | 'sms'>('email')
  const [localClient, setLocalClient] = useState<Client>(client)

  function handleBanSuccess(updated: Client) {
    setLocalClient(updated)
    onClientUpdate?.(updated)
