    },
    {
      icon: CalendarClock,
      label: 'Next booking',
      value: nextBookingDate
        ? new Date(nextBookingDate).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })
        : 'None scheduled',
      muted: !nextBookingDate,
