                  </DropdownMenuContent>
                </DropdownMenu>
              )}
            </div>

            {/* Send message button — desktop only */}
            <div className="hidden md:flex">
              <Button
                variant="outline"
                size="sm"
                disabled={isBanned}
                onClick={() => {
                  setComposerChannel(localClient.preferred_contact === 'sms' ? 'sms' : 'email')
                  setComposerOpen(true)
                }}
                aria-label="Send message"
              >
                <MessageSquare className="mr-2 h-4 w-4" aria-hidden="true" />
                Message
              </Button>
            </div>

            {/* Upload photo — desktop only */}
            <div className="hidden md:flex">
              <Button variant="outline" size="sm" onClick={onUploadPhoto} aria-label="Upload photo">
                <Camera className="mr-2 h-4 w-4" aria-hidden="true" />
                Upload photo
              </Button>
            </div>

            {/* More menu */}
            <DropdownMenu>
              <DropdownMenuTrigger render={
                <Button variant="outline" size="sm" aria-label="More actions">
                  <MoreHorizontal className="h-4 w-4" aria-hidden="true" />
                </Button>
              } />
              <DropdownMenuContent align="end">
                {onEdit && (
                  <DropdownMenuItem onClick={onEdit}>
                    Edit client
                  </DropdownMenuItem>
                )}
                <DropdownMenuItem>
                  <Tag className="mr-2 h-4 w-4" aria-hidden="true" />
                  Add tag
                </DropdownMenuItem>
                {/* Mobile-only message actions */}
                <DropdownMenuItem
                  className="md:hidden"
                  disabled={isBanned}
                  onClick={() => {
                    setComposerChannel('sms')
                    setComposerOpen(true)
                  }}
                >
                  <MessageSquare className="mr-2 h-4 w-4" aria-hidden="true" />
                  Send SMS
                </DropdownMenuItem>
                <DropdownMenuItem
                  className="md:hidden"
                  disabled={isBanned}
                  onClick={() => {
                    setComposerChannel('email')
                    setComposerOpen(true)
                  }}
                >
                  <Mail className="mr-2 h-4 w-4" aria-hidden="true" />
                  Send email
                </DropdownMenuItem>
                <DropdownMenuItem className="md:hidden" onClick={onUploadPhoto}>
                  <Camera className="mr-2 h-4 w-4" aria-hidden="true" />
                  Upload photo
                </DropdownMenuItem>
                <DropdownMenuSeparator />
                <Link href={`/api/clients/export?ids=${localClient.id}`} download>
                  <DropdownMenuItem>
                    <Download className="mr-2 h-4 w-4" aria-hidden="true" />
                    Export client data
                  </DropdownMenuItem>
                </Link>
                <DropdownMenuSeparator />
                {isArchived ? (
                  onUnarchive && (
                    <DropdownMenuItem onClick={onUnarchive}>
                      <Archive className="mr-2 h-4 w-4" aria-hidden="true" />
                      Unarchive
                    </DropdownMenuItem>
                  )
                ) : (
                  onArchive && (
                    <DropdownMenuItem
                      onClick={onArchive}
                      className="text-destructive focus:text-destructive"
                    >
                      <Archive className="mr-2 h-4 w-4" aria-hidden="true" />
                      Archive client
                    </DropdownMenuItem>
                  )
                )}
                {/* Ban / unban — owner/admin only */}
                {canBan && (
                  <>
                    <DropdownMenuSeparator />
                    <DropdownMenuItem
                      onClick={() => setBanDialogOpen(true)}
                      className={cn(
                        isBanned
                          ? 'text-foreground'
                          : 'text-destructive focus:text-destructive'
                      )}
                    >
                      <Ban className="mr-2 h-4 w-4" aria-hidden="true" />
                      {isBanned ? 'Unban client' : 'Ban client'}
                    </DropdownMenuItem>
                  </>
                )}
                <DropdownMenuItem
                  className={cn('text-destructive focus:text-destructive', 'opacity-50 cursor-not-allowed')}
                  disabled
                >
                  <Trash2 className="mr-2 h-4 w-4" aria-hidden="true" />
                  Delete client
                </DropdownMenuItem>
              </DropdownMenuContent>
            </DropdownMenu>
          </div>
        </div>
      </div>

      {/* Ban dialog */}
      <BanClientDialog
        open={banDialogOpen}
        onOpenChange={setBanDialogOpen}
        client={localClient}
        onSuccess={handleBanSuccess}
      />

      {/* Message composer */}
      <MessageComposer
        open={composerOpen}
        onOpenChange={setComposerOpen}
        client={localClient}
        defaultChannel={composerChannel}
      />
    </>
  )
}

