import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { ClientCommsTab } from '@/components/clients/comms/ClientCommsTab'
import type { Database } from '@/lib/supabase/types'

type Client = Database['public']['Tables']['clients']['Row']

interface Props {
  params: Promise<{ id: string }>
  searchParams: Promise<{ starred?: string }>
}

export const metadata: Metadata = { title: 'Client Communications' }

export default async function Page({ params, searchParams }: Props) {
  const { id } = await params
  const { starred } = await searchParams

  const auth = await getAuthenticatedUser()
  if (!auth) redirect('/login')

  const supabase = await createClient()

  const [commsResult, clientResult] = await Promise.all([
    supabase
      .from('client_communications')
      .select('id, studio_id, client_id, booking_id, conversation_id, channel, direction, status, subject, body, template, sent_at, delivered_at, opened_at, error, provider_message_id, metadata, created_at, updated_at')
      .eq('client_id', id)
      .eq('studio_id', auth.studioId)
      .order('created_at', { ascending: false }),
    supabase
      .from('clients')
      .select('id, first_name, last_name, email, phone, preferred_contact, is_banned')
      .eq('id', id)
      .eq('studio_id', auth.studioId)
      .single(),
  ])

  if (!clientResult.data) redirect('/clients')

  return (
    <ClientCommsTab
      clientId={id}
      client={clientResult.data as Client}
      initialComms={commsResult.data ?? []}
      starredOnly={starred === 'true'}
    />
  )
}

