import type { InboxItemKind } from '@/lib/supabase/types'

// ─── Types ────────────────────────────────────────────────────

type ActionResult<T = undefined> =
  | { ok: true; data?: T; error?: never }
  | { ok: false; error: string; data?: never }

interface BatchItem {
  kind: InboxItemKind
  id: string
}

/** Subset of InboxItemKind that inbox_assignments supports (excludes 'unread-message') */
type DBInboxItemKind = 'deposit' | 'form' | 'waitlist' | 'client'

function isDBInboxKind(kind: InboxItemKind): kind is DBInboxItemKind {
  return kind === 'deposit' || kind === 'form' || kind === 'waitlist' || kind === 'client'
}

// ─── Helpers ──────────────────────────────────────────────────

async function upsertAssignment(
  studioId: string,
  itemKind: InboxItemKind,
  itemId: string,
  patch: Record<string, string | null | boolean>,
): Promise<ActionResult> {
  // 'unread-message' items are conversations — inbox_assignments doesn't store them
  if (!isDBInboxKind(itemKind)) {
    return { ok: true }
  }

  const supabase = await createClient()

  const { error } = await supabase
    .from('inbox_assignments')
    .upsert(
      {
        studio_id: studioId,
        item_kind: itemKind,
        item_id: itemId,
        ...patch,
        updated_at: new Date().toISOString(),
      },
      { onConflict: 'studio_id,item_kind,item_id' },
    )

